    uint32_t version;
    uint32_t next_value;

    // Skip initial bytes
    if (avio_skip(avctx->pb, 16) < 0)
        return AVERROR(EIO);

    version = avio_rl32(avctx->pb);
    if (version == 2) {
        AVStream *astream = avformat_new_stream(avctx, NULL);
        AVStream *vstream = avformat_new_stream(avctx, NULL);
        if (!astream || !vstream)
            return AVERROR(ENOMEM);

        astream->codecpar->codec_type = AVMEDIA_TYPE_AUDIO;
        astream->codecpar->sample_rate = avio_rl32(avctx->pb);
        astream->codecpar->channels = avio_rl16(avctx->pb);
        astream->codecpar->sample_fmt = avio_rl16(avctx->pb);

        vstream->codecpar->codec_type = AVMEDIA_TYPE_VIDEO;
        vstream->codecpar->width = avio_rl32(avctx->pb);
        vstream->codecpar->height = avio_rl32(avctx->pb);
        vstream->codecpar->format = avio_rl16(avctx->pb);

        // Read metadata and frame info
        if (avio_read(avctx->pb, NULL, 256) < 0)
            return AVERROR(EIO);

    } else if (version == 0) {
        next_value = avio_rl32(avctx->pb);
        if (next_value == 3) {
            int track_count = avio_r8(avctx->pb);
            for (int i = 0; i < track_count; i++) {
                AVStream *track = avformat_new_stream(avctx, NULL);
                if (!track)
                    return AVERROR(ENOMEM);

                track->codecpar->codec_type = avio_r8(avctx->pb) == 0 ? AVMEDIA_TYPE_AUDIO : AVMEDIA_TYPE_VIDEO;
                if (track->codecpar->codec_type == AVMEDIA_TYPE_AUDIO) {
                    track->codecpar->sample_rate = avio_rl32(avctx->pb);
                    track->codecpar->channels = avio_rl16(avctx->pb);
                } else {
                    track->codecpar->width = avio_rl32(avctx->pb);
                    track->codecpar->height = avio_rl32(avctx->pb);
                }
            }
            // Read tables and indices
            if (avio_read(avctx->pb, NULL, 1024) < 0)
                return AVERROR(EIO);
        }
    } else {
        return AVERROR_PATCHWELCOME;
    }

    return 0;
}

